/* WellStream Platform - Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600;700&display=swap');

:root {
  /* Brand Colors */
  --navy: #0D1B2A;
  --navy-dark: #081420;
  --charcoal: #1B2838;
  --slate: #2D3E50;
  --teal: #00B4D8;
  --teal-dark: #0077B6;
  --accent-green: #6CC24A;
  --white: #FFFFFF;
  --gray-100: #F8FAFC;
  --gray-200: #E2E8F0;
  --gray-400: #94A3B8;
  --gray-600: #475569;
  --gray-800: #1E293B;

  /* Semantic */
  --bg-primary: var(--navy-dark);
  --bg-secondary: var(--navy);
  --bg-card: var(--charcoal);
  --text-primary: var(--white);
  --text-secondary: var(--gray-400);
  --text-muted: var(--gray-600);
  --accent: var(--teal);
  --accent-hover: var(--teal-dark);
  --success: var(--accent-green);

  /* Typography */
  --font-display: 'Space Grotesk', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Border */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 2px 4px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.5);
  --shadow-glow: 0 0 30px rgba(0,180,216,0.3);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Typography Scale */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: clamp(1.25rem, 2vw, 1.5rem); }

p { max-width: 65ch; }

a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
}

/* Layout */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.section {
  padding: var(--space-4xl) 0;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(8, 20, 32, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  padding: 0 var(--space-lg);
  max-width: 1400px;
  margin: 0 auto;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--white);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.nav-logo svg {
  width: 32px;
  height: 32px;
  fill: var(--accent);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
  list-style: none;
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-trigger {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  color: var(--text-secondary);
  font-weight: 500;
  cursor: pointer;
  padding: var(--space-sm) 0;
  transition: color 0.2s;
}

.nav-dropdown-trigger:hover,
.nav-dropdown-trigger.active {
  color: var(--white);
}

.nav-dropdown-trigger svg {
  width: 16px;
  height: 16px;
  transition: transform 0.2s;
}

.nav-dropdown:hover .nav-dropdown-trigger svg {
  transform: rotate(180deg);
}

.nav-dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 200px;
  background: var(--bg-card);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  padding: var(--space-sm);
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px);
  transition: all 0.2s ease;
  box-shadow: var(--shadow-lg);
}

.nav-dropdown:hover .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown-item {
  display: block;
  padding: var(--space-sm) var(--space-md);
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: all 0.15s;
}

.nav-dropdown-item:hover {
  background: rgba(255,255,255,0.05);
  color: var(--white);
}

.nav-cta {
  background: var(--accent);
  color: var(--navy-dark) !important;
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-full);
  font-weight: 600;
  transition: all 0.2s;
}

.nav-cta:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-glow);
}

/* Mobile Nav */
.nav-mobile-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--white);
  cursor: pointer;
  padding: var(--space-sm);
}

.nav-mobile-toggle svg {
  width: 24px;
  height: 24px;
}

@media (max-width: 968px) {
  .nav-links {
    display: none;
  }

  .nav-mobile-toggle {
    display: block;
  }
}

/* Hero Section */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding-top: 72px;
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 50%, var(--charcoal) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background:
    radial-gradient(ellipse at 20% 50%, rgba(0,180,216,0.1) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 80%, rgba(108,194,74,0.05) 0%, transparent 40%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  background: rgba(0,180,216,0.15);
  border: 1px solid rgba(0,180,216,0.3);
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  color: var(--teal);
  margin-bottom: var(--space-lg);
}

.hero-badge::before {
  content: '';
  width: 8px;
  height: 8px;
  background: var(--teal);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.hero-title {
  margin-bottom: var(--space-lg);
  background: linear-gradient(135deg, var(--white) 0%, var(--gray-200) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-xl);
  max-width: 540px;
}

.hero-cta {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

.hero-visual-inner {
  position: relative;
  background: linear-gradient(135deg, var(--charcoal) 0%, var(--slate) 100%);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 1px solid rgba(255,255,255,0.1);
  box-shadow: var(--shadow-lg);
}

@media (max-width: 968px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-subtitle {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-cta {
    justify-content: center;
  }

  .hero-visual {
    display: none;
  }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-md) var(--space-xl);
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: var(--navy-dark);
}

.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
  color: var(--navy-dark);
}

.btn-secondary {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.3);
}

.btn-secondary:hover {
  border-color: var(--white);
  background: rgba(255,255,255,0.05);
  color: var(--white);
}

.btn-sm {
  padding: var(--space-sm) var(--space-lg);
  font-size: 0.875rem;
}

/* Featured Product Banner */
.featured-banner {
  background: linear-gradient(135deg, var(--accent-green) 0%, #4a9c2e 100%);
  padding: var(--space-xl) 0;
}

.featured-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-lg);
}

.featured-product {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.featured-product-icon {
  width: 56px;
  height: 56px;
  background: rgba(255,255,255,0.2);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
}

.featured-product-icon svg {
  width: 32px;
  height: 32px;
  fill: var(--white);
}

.featured-product-info h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-xs);
}

.featured-product-info p {
  color: rgba(255,255,255,0.8);
  font-size: 0.875rem;
}

@media (max-width: 768px) {
  .featured-banner-inner {
    flex-direction: column;
    text-align: center;
  }
}

/* Use Cases Section */
.use-cases {
  background: var(--bg-secondary);
}

.section-header {
  text-align: center;
  max-width: 800px;
  margin: 0 auto var(--space-3xl);
}

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
  margin-bottom: var(--space-md);
}

.section-title {
  margin-bottom: var(--space-md);
}

.section-desc {
  color: var(--text-secondary);
  font-size: 1.125rem;
}

/* Industry Tabs */
.industry-tabs {
  display: flex;
  justify-content: center;
  gap: var(--space-xs);
  margin-bottom: var(--space-xl);
  flex-wrap: wrap;
}

.industry-tab {
  padding: var(--space-sm) var(--space-lg);
  background: transparent;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-full);
  color: var(--text-secondary);
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.industry-tab:hover {
  border-color: rgba(255,255,255,0.3);
  color: var(--white);
}

.industry-tab.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--navy-dark);
}

/* Use Case Cards Grid */
.use-case-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.use-case-card {
  background: var(--bg-card);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  transition: all 0.3s ease;
}

.use-case-card:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.use-case-icon {
  width: 48px;
  height: 48px;
  background: rgba(0,180,216,0.15);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-md);
}

.use-case-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
}

.use-case-card h4 {
  font-size: 1.125rem;
  margin-bottom: var(--space-sm);
}

.use-case-card p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

@media (max-width: 1024px) {
  .use-case-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .use-case-grid {
    grid-template-columns: 1fr;
  }
}

/* Platform Ecosystem Diagram */
.platform-diagram {
  background: var(--bg-primary);
  position: relative;
}

.diagram-container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
  position: relative;
}

.diagram-pillar {
  background: linear-gradient(180deg, var(--charcoal) 0%, var(--navy) 100%);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  text-align: center;
  position: relative;
  transition: all 0.3s;
}

.diagram-pillar:hover {
  border-color: rgba(0,180,216,0.4);
  transform: translateY(-4px);
}

.diagram-pillar::after {
  content: '';
  position: absolute;
  top: 50%;
  right: -24px;
  width: 48px;
  height: 2px;
  background: linear-gradient(90deg, var(--accent), transparent);
}

.diagram-pillar:last-child::after {
  display: none;
}

.diagram-icon {
  width: 64px;
  height: 64px;
  background: rgba(0,180,216,0.1);
  border: 2px solid var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-lg);
}

.diagram-icon svg {
  width: 32px;
  height: 32px;
  stroke: var(--accent);
}

.diagram-pillar h4 {
  margin-bottom: var(--space-sm);
  color: var(--white);
}

.diagram-pillar p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

@media (max-width: 968px) {
  .diagram-container {
    grid-template-columns: 1fr;
  }

  .diagram-pillar::after {
    display: none;
  }
}

/* Company Culture Section */
.company-culture {
  background: var(--bg-secondary);
}

.culture-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.culture-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.culture-stat {
  text-align: center;
  padding: var(--space-lg);
  background: var(--bg-card);
  border-radius: var(--radius-lg);
}

.culture-stat-number {
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
}

.culture-stat-label {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-top: var(--space-sm);
}

@media (max-width: 968px) {
  .culture-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .culture-stats {
    grid-template-columns: 1fr;
  }
}

/* Renewables CTA */
.renewables-cta {
  background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.renewables-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2xl);
}

.renewables-info h3 {
  margin-bottom: var(--space-sm);
}

.renewables-info p {
  color: var(--text-secondary);
  max-width: 500px;
}

@media (max-width: 768px) {
  .renewables-inner {
    flex-direction: column;
    text-align: center;
  }
}

/* Footer */
.footer {
  background: var(--navy-dark);
  padding: var(--space-3xl) 0 var(--space-xl);
  border-top: 1px solid rgba(255,255,255,0.05);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-2xl);
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .nav-logo {
  margin-bottom: var(--space-md);
}

.footer-brand p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-col h5 {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--white);
  margin-bottom: var(--space-md);
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: var(--space-sm);
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255,255,255,0.05);
}

.footer-bottom p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.footer-logins {
  display: flex;
  gap: var(--space-md);
}

.footer-login {
  color: var(--text-secondary);
  font-size: 0.875rem;
  padding: var(--space-sm) var(--space-md);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  transition: all 0.2s;
}

.footer-login:hover {
  border-color: var(--accent);
  color: var(--accent);
}

@media (max-width: 968px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-brand {
    grid-column: span 2;
    max-width: none;
  }
}

@media (max-width: 640px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: 1;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--bg-card);
  border-top: 1px solid rgba(255,255,255,0.1);
  padding: var(--space-lg);
  z-index: 9999;
  transform: translateY(100%);
  transition: transform 0.3s ease;
}

.cookie-banner.visible {
  transform: translateY(0);
}

.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-lg);
  max-width: 1280px;
  margin: 0 auto;
}

.cookie-text {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
}

.cookie-btn {
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.cookie-btn-decline {
  background: transparent;
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--text-secondary);
}

.cookie-btn-decline:hover {
  border-color: var(--white);
  color: var(--white);
}

.cookie-btn-accept {
  background: var(--accent);
  border: none;
  color: var(--navy-dark);
}

.cookie-btn-accept:hover {
  background: var(--accent-hover);
}

/* Platform Overview Page */
.page-hero {
  padding: 160px 0 80px;
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 100%);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: radial-gradient(ellipse at 50% 0%, rgba(0,180,216,0.1) 0%, transparent 60%);
  pointer-events: none;
}

/* Platform Benefits */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-lg);
}

.benefit-card {
  background: var(--bg-card);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  text-align: center;
  transition: all 0.3s;
}

.benefit-card:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
}

.benefit-icon {
  width: 56px;
  height: 56px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-md);
}

.benefit-icon svg {
  width: 28px;
  height: 28px;
  stroke: var(--accent);
}

.benefit-card h4 {
  font-size: 1rem;
  margin-bottom: var(--space-sm);
}

.benefit-card p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

@media (max-width: 1024px) {
  .benefits-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .benefits-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 480px) {
  .benefits-grid {
    grid-template-columns: 1fr;
  }
}

/* Stats Section */
.stats-section {
  background: var(--bg-secondary);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.stat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: var(--space-2xl);
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  border: 1px solid rgba(255,255,255,0.05);
}

.stat-ring {
  position: relative;
  width: 160px;
  height: 160px;
  margin-bottom: var(--space-lg);
}

.stat-ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.stat-ring-bg {
  fill: none;
  stroke: var(--charcoal);
  stroke-width: 8;
}

.stat-ring-fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 440;
  stroke-dashoffset: 440;
  transition: stroke-dashoffset 1.5s ease-out;
}

.stat-ring-fill.animate {
  stroke-dashoffset: var(--target-offset);
}

.stat-value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-display);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--white);
}

.stat-value span {
  font-size: 1.5rem;
  color: var(--accent);
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

@media (max-width: 768px) {
  .stats-grid {
    grid-template-columns: 1fr;
  }
}

/* Implementation Timeline */
.timeline-section {
  background: var(--bg-primary);
}

.timeline {
  display: flex;
  justify-content: space-between;
  position: relative;
  margin-top: var(--space-2xl);
}

.timeline::before {
  content: '';
  position: absolute;
  top: 40px;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--charcoal);
  border-radius: 2px;
}

.timeline-item {
  flex: 1;
  text-align: center;
  position: relative;
  padding: 0 var(--space-md);
}

.timeline-marker {
  width: 80px;
  height: 80px;
  background: var(--bg-card);
  border: 3px solid var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-lg);
  position: relative;
  z-index: 1;
}

.timeline-marker span {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--accent);
}

.timeline-item h4 {
  margin-bottom: var(--space-xs);
}

.timeline-item p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

@media (max-width: 768px) {
  .timeline {
    flex-direction: column;
    gap: var(--space-xl);
  }

  .timeline::before {
    top: 0;
    bottom: 0;
    left: 40px;
    right: auto;
    width: 4px;
    height: auto;
  }

  .timeline-item {
    text-align: left;
    padding-left: 100px;
  }

  .timeline-marker {
    position: absolute;
    left: 0;
    margin: 0;
  }
}

/* Accordion */
.accordion {
  max-width: 900px;
  margin: 0 auto;
}

.accordion-item {
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-md);
  overflow: hidden;
  background: var(--bg-card);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-lg) var(--space-xl);
  background: transparent;
  border: none;
  color: var(--white);
  font-size: 1.125rem;
  font-weight: 600;
  font-family: var(--font-display);
  cursor: pointer;
  transition: all 0.2s;
  text-align: left;
}

.accordion-trigger:hover {
  background: rgba(255,255,255,0.02);
}

.accordion-trigger svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
  transition: transform 0.3s;
  flex-shrink: 0;
}

.accordion-item.open .accordion-trigger svg {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.accordion-item.open .accordion-content {
  max-height: 500px;
}

.accordion-body {
  padding: 0 var(--space-xl) var(--space-xl);
  color: var(--text-secondary);
}

/* Data Lifecycle Diagram */
.lifecycle-diagram {
  background: var(--bg-secondary);
}

.lifecycle-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.lifecycle-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: var(--space-lg);
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  min-width: 120px;
  border: 1px solid rgba(255,255,255,0.05);
  transition: all 0.3s;
}

.lifecycle-step:hover {
  border-color: rgba(0,180,216,0.3);
  transform: translateY(-4px);
}

.lifecycle-step-icon {
  width: 48px;
  height: 48px;
  background: rgba(0,180,216,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-sm);
}

.lifecycle-step-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
}

.lifecycle-step span {
  font-weight: 600;
  font-size: 0.875rem;
}

.lifecycle-arrow {
  color: var(--accent);
  font-size: 1.5rem;
}

@media (max-width: 768px) {
  .lifecycle-flow {
    flex-direction: column;
  }

  .lifecycle-arrow {
    transform: rotate(90deg);
  }
}

/* Testimonials */
.testimonials-section {
  background: var(--bg-primary);
}

.testimonial-carousel {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: var(--space-2xl);
  background: var(--bg-card);
  border-radius: var(--radius-xl);
  border: 1px solid rgba(255,255,255,0.05);
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text-primary);
  margin-bottom: var(--space-lg);
  line-height: 1.6;
}

.testimonial-author {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.testimonial-author strong {
  color: var(--white);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-xl);
}

.testimonial-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--charcoal);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.testimonial-dot.active {
  background: var(--accent);
  transform: scale(1.2);
}

/* Security Page */
.security-tabs {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-2xl);
}

.security-tab {
  padding: var(--space-md) var(--space-2xl);
  background: transparent;
  border: 2px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-full);
  color: var(--text-secondary);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s;
}

.security-tab:hover {
  border-color: rgba(255,255,255,0.3);
  color: var(--white);
}

.security-tab.active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--navy-dark);
}

.security-content {
  display: none;
}

.security-content.active {
  display: block;
}

.security-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
}

.security-feature {
  display: flex;
  gap: var(--space-lg);
  padding: var(--space-xl);
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid rgba(255,255,255,0.05);
}

.security-feature-icon {
  width: 56px;
  height: 56px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.security-feature-icon svg {
  width: 28px;
  height: 28px;
  stroke: var(--accent);
}

.security-feature h4 {
  margin-bottom: var(--space-sm);
}

.security-feature p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

@media (max-width: 768px) {
  .security-features-grid {
    grid-template-columns: 1fr;
  }
}

/* Integration Page */
.integration-tabs {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-2xl);
  flex-wrap: wrap;
}

.integration-tab {
  padding: var(--space-md) var(--space-2xl);
  background: transparent;
  border: 2px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-full);
  color: var(--text-secondary);
  font-weight: 600;
  font-size: 1rem;
